    31  /*
    32   * https://brandur.org/logfmt
    33   * https://godoc.org/github.com/kr/logfmt
    34   *
    35   * ident_byte = any byte greater than ' ', excluding '=' and '"'
    36   * string_byte = any byte excluding '"' and '\'
    37   * garbage = !ident_byte
    38   * ident = ident_byte, { ident byte }
    39   * key = ident
    40   * value = ident | '"', { string_byte | '\', '"' }, '"'
    41   * pair = key, '=', value | key, '=' | key
    42   * message = { garbage, pair }, garbage
    43   */
